//! The seeds must be the web's bytes exactly (tests/vectors/seeds.json,
//! generated by the web's Yjs): two implementations, one encoding.

use kutup_collab::{seed_list, seed_list_upload, seed_text, seed_text_upload, Place};
use serde_json::Value;

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

#[test]
fn seeds_match_the_web() {
    let v: Value = serde_json::from_str(include_str!("vectors/seeds.json")).unwrap();
    let file_id = v["fileId"].as_str().unwrap();
    for case in v["texts"].as_array().unwrap() {
        assert_eq!(
            hex(&seed_text(file_id, case["text"].as_str().unwrap())),
            case["seed"].as_str().unwrap(),
            "{}",
            case["name"]
        );
    }
    let places: Vec<Place> = v["list"]["places"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| Place {
            id: p["id"].as_str().unwrap().into(),
            name: p["name"].as_str().unwrap().into(),
            note: p["note"].as_str().unwrap().into(),
            lat: p["lat"].as_f64().unwrap(),
            lon: p["lon"].as_f64().unwrap(),
            added_by: p["addedBy"].as_str().unwrap().into(),
            added_at: p["addedAt"].as_str().unwrap().into(),
        })
        .collect();
    assert_eq!(
        hex(&seed_list(file_id, &places)),
        v["list"]["seed"].as_str().unwrap()
    );
    // From the files' bytes, as an editor reads them.
    let unhex = |s: &str| -> Vec<u8> {
        (0..s.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
            .collect()
    };
    for case in v["textUploads"].as_array().unwrap() {
        assert_eq!(
            hex(&seed_text_upload(
                file_id,
                &unhex(case["bytes"].as_str().unwrap())
            )),
            case["seed"].as_str().unwrap(),
            "{}",
            case["name"]
        );
    }
    for case in v["listUploads"].as_array().unwrap() {
        assert_eq!(
            hex(&seed_list_upload(
                file_id,
                &unhex(case["bytes"].as_str().unwrap())
            )),
            case["seed"].as_str().unwrap(),
            "{}",
            case["name"]
        );
    }
}
